<body>

<div class="noise-monitor" id="monitor">
  <div class="monitor-bg"></div>
  <div class="scan-line"></div>
  <div class="header-tag">NEURAL_NOISE // LIVE_FEED</div>
  <div id="particles-container"></div>
  <div class="detail-overlay" id="overlay">
    <div class="close-btn" onclick="closeDetail()">×</div>
    <div class="detail-meta">DECODED_FRAGMENT:</div>
    <div class="detail-text" id="detail-content">...</div>
  </div>
</div>

<script>
  // 动态注入点：9个对象，18个占位符
  const thoughts = [
    { key: "$1", content: "$2" },
    { key: "$3", content: "$4" },
    { key: "$5", content: "$6" },
    { key: "$7", content: "$8" },
    { key: "$9", content: "$10" },
    { key: "$11", content: "$12" },
    { key: "$13", content: "$14" },
    { key: "$15", content: "$16" },
    { key: "$17", content: "$18" }
  ];

  const container = document.getElementById('particles-container');
  const overlay = document.getElementById('overlay');
  const detailContent = document.getElementById('detail-content');
  let activeElement = null;

  function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  function initParticles() {
    const rows = 3; const cols = 3;
    const cellWidth = 100 / cols; const cellHeight = 100 / rows;
    let gridIndices = shuffle(Array.from({length: rows * cols}, (_, i) => i));

    thoughts.forEach((thought, index) => {
      const gridIndex = gridIndices[index % gridIndices.length];
      const row = Math.floor(gridIndex / cols);
      const col = gridIndex % cols;
      const baseX = col * cellWidth;
      const baseY = row * cellHeight;
      const jitterX = Math.random() * (cellWidth - 30) + 5; 
      const jitterY = Math.random() * (cellHeight - 20) + 10;

      const el = document.createElement('div');
      el.className = 'thought-particle';
      el.innerText = `“${thought.key}”`;

      const randomSize = (0.8 + Math.random() * 0.7).toFixed(1);
      el.style.fontSize = `${randomSize}rem`;
      el.style.left = `calc(${baseX}% + ${jitterX}%)`;
      el.style.top = `calc(${baseY}% + ${jitterY}%)`;

      const moveAnimType = Math.floor(Math.random() * 4) + 1;
      const moveDuration = 10 + Math.random() * 10; 
      const strobeDuration = 2 + Math.random() * 5; 
      const strobeDelay = Math.random() * -5;

      el.style.animation = `float-${moveAnimType} ${moveDuration}s ease-in-out infinite alternate, color-strobe ${strobeDuration}s step-end infinite ${strobeDelay}s`;
      el.addEventListener('click', (e) => { e.stopPropagation(); activateThought(el, thought.content); });
      container.appendChild(el);
    });
  }

  function activateThought(el, content) {
    if (activeElement) {
      activeElement.classList.remove('active');
      activeElement.style.animation = activeElement.dataset.anim;
      activeElement.style.fontSize = activeElement.dataset.size;
    }
    el.dataset.anim = el.style.animation;
    el.dataset.size = el.style.fontSize;
    el.style.animation = 'none'; void el.offsetWidth;
    el.classList.add('active');
    activeElement = el;
    detailContent.innerText = `“${content}”`;
    overlay.classList.add('visible');
  }

  function closeDetail() {
    overlay.classList.remove('visible');
    if (activeElement) {
      activeElement.classList.remove('active');
      activeElement.style.animation = activeElement.dataset.anim;
      activeElement.style.fontSize = activeElement.dataset.size;
      activeElement = null;
    }
  }

  document.getElementById('monitor').addEventListener('click', () => { closeDetail(); });
  initParticles();
</script>
</body>
</html>
