<div class="memory-projector">
  <div class="viewport">
    <div class="film-grain"></div>
    <div class="scratch-line"></div>
    <div class="scratch-line"></div>
    <div class="vignette"></div>
    <div class="flicker-overlay" id="flicker"></div>
    <div class="film-reel" id="reel"></div>
  </div>
  <div class="controls">
    <button class="btn" onclick="prevFrame()">◀ PREV</button>
    <div class="counter" id="counter">01 / 05</div>
    <button class="btn" onclick="nextFrame()">NEXT ▶</button>
  </div>
</div>
<script>
  // 注入点：10个占位符
  const memories = [
    { title: "$1", desc: "$2", bg: "linear-gradient(135deg, #4a3b2a, #2a1d12)" },
    { title: "$3", desc: "$4", bg: "linear-gradient(45deg, #2c3e50, #8e44ad)" },
    { title: "$5", desc: "$6", bg: "linear-gradient(to bottom, #3b2e2a, #800000)" },
    { title: "$7", desc: "$8", bg: "linear-gradient(to top, #1a1a1a, #2c3e50)" },
    { title: "$9", desc: "$10", bg: "linear-gradient(180deg, #000000, #162447)" }
  ];

  let currentIndex = 0;
  const reel = document.getElementById('reel');
  const counter = document.getElementById('counter');
  const flicker = document.getElementById('flicker');

  function initReel() {
    memories.forEach((mem, index) => {
      const frame = document.createElement('div');
      frame.className = 'memory-frame';
      frame.innerHTML = `<div class="memory-bg" style="background: ${mem.bg}"></div><div class="memory-content"><div class="memory-title">NO.${index + 1} ${mem.title}</div><div class="memory-desc">${mem.desc}</div></div>`;
      reel.appendChild(frame);
    });
    updateCounter();
  }
  function updateCounter() { counter.innerText = `0${currentIndex + 1} / 0${memories.length}`; }
  function triggerFlicker() { flicker.classList.add('active'); setTimeout(() => { flicker.classList.remove('active'); }, 150); }
  function nextFrame() { if (currentIndex < memories.length - 1) { triggerFlicker(); currentIndex++; updateTransform(); } }
  function prevFrame() { if (currentIndex > 0) { triggerFlicker(); currentIndex--; updateTransform(); } }
  function updateTransform() { reel.style.transform = `translateX(-${currentIndex * 100}%)`; updateCounter(); }
  initReel();
</script>
</body>
