<script>
  // 注入点：3个页面对象，30个占位符
  const newsData = [
    {
      headline: { title: "$1", sub: "$2", text: "$3" },
      snippets: [
        { area: "$4", title: "$5", text: "$6" },
        { area: "$7", title: "$8", text: "$9" }
      ]
    },
    {
      headline: { title: "$10", sub: "$11", text: "$12" },
      snippets: [
        { area: "$13", title: "$14", text: "$15" },
        { area: "$16", title: "$17", text: "$18" }
      ]
    },
    {
      headline: { title: "$19", sub: "$20", text: "$21" },
      snippets: [
        { area: "$22", title: "$23", text: "$24" },
        { area: "$25", title: "$26", text: "$27" }
      ]
    }
  ];

  let currentPage = 0;
  const contentArea = document.getElementById('content-area');

  function renderPage(index) {
    const data = newsData[index];
    let html = `
      <div class="grid-layout">
        <div class="headline-section">
          <div class="headline-content">
            <div class="headline">${data.headline.title}</div>
            <div class="subhead">${data.headline.sub}</div>
            <div class="article-text">${data.headline.text}</div>
          </div>
          <div class="controls">
            <span class="page-btn" onclick="prevPage()">← PREV</span>
            <span id="page-num">PAGE ${index + 1}</span>
            <span class="page-btn" onclick="nextPage()">NEXT →</span>
          </div>
        </div>
        <div class="sidebar">
          ${data.snippets.map(snip => `
            <div class="snippet">
              <span class="tag" data-area="${snip.area}">${snip.area}</span>
              <div class="snippet-title">${snip.title}</div>
              <div class="snippet-body">${snip.text}</div>
            </div>
          `).join('')}
        </div>
      </div>
    `;
    contentArea.innerHTML = html;
    const months = ["01", "02", "03", "11", "12"];
    const days = Math.floor(Math.random() * 28) + 1;
    document.getElementById('date-display').innerText = `202X年 ${months[Math.floor(Math.random()*months.length)]}月${days}日`;
  }

  function nextPage() { if (currentPage < newsData.length - 1) { currentPage++; renderPage(currentPage); } else { currentPage = 0; renderPage(currentPage); } }
  function prevPage() { if (currentPage > 0) { currentPage--; renderPage(currentPage); } else { currentPage = newsData.length - 1; renderPage(currentPage); } }

  renderPage(0);
</script>
</body>
</html>
