      btn.classList.remove('active');
    });

    // 隐藏所有面板
    document.querySelectorAll('.tab-panel').forEach(panel => {
      panel.classList.remove('active');
    });

    // 激活对应的按钮和面板
    event.target.classList.add('active');
    document.getElementById('panel-' + tabId).classList.add('active');
  }
