    <script>
        // Slider value display
        document.getElementById('introExtro').addEventListener('input', function() {
            document.getElementById('introExtroValue').textContent = this.value;
        });

        document.getElementById('emotionExpress').addEventListener('input', function() {
            document.getElementById('emotionExpressValue').textContent = this.value;
        });

        // Form submission
        document.getElementById('characterForm').addEventListener('submit', function(e) {
            e.preventDefault();
            generateProfile();
        });

        function generateProfile() {
            const data = {
                name: document.getElementById('name').value,
                age: document.getElementById('age').value,
                gender: document.getElementById('gender').value,
                occupation: document.getElementById('occupation').value,
                district: document.getElementById('district').value,
                height: document.getElementById('height').value,
                bodyType: document.getElementById('bodyType').value,
                appearance: document.getElementById('appearance').value,
                styles: Array.from(document.querySelectorAll('input[name="style"]:checked')).map(cb => cb.value),
                personalities: Array.from(document.querySelectorAll('input[name="personality"]:checked')).map(cb => cb.value),
                introExtro: document.getElementById('introExtro').value,
                emotionExpress: document.getElementById('emotionExpress').value,
                personalityNote: document.getElementById('personalityNote').value,
                hobbies: Array.from(document.querySelectorAll('input[name="hobby"]:checked')).map(cb => cb.value),
                musicPrefs: Array.from(document.querySelectorAll('input[name="music"]:checked')).map(cb => cb.value),
                hobbyNote: document.getElementById('hobbyNote').value,
                skills: Array.from(document.querySelectorAll('input[name="skill"]:checked')).map(cb => cb.value),
                talents: Array.from(document.querySelectorAll('input[name="talent"]:checked')).map(cb => cb.value),
                skillNote: document.getElementById('skillNote').value,
                whyHere: document.getElementById('whyHere').value,
                pastShadow: document.getElementById('pastShadow').value,
                currentState: document.getElementById('currentState').value,
                birthday: document.getElementById('birthday').value,
                zodiac: document.getElementById('zodiac').value,
                chineseZodiac: document.getElementById('chineseZodiac').value,
                residence: document.getElementById('residence').value,
                foodPref: document.getElementById('foodPref').value,
                sleepHabit: document.getElementById('sleepHabit').value,
                pet: document.getElementById('pet').value,
                otherInfo: document.getElementById('otherInfo').value,
                meetingWay: document.getElementById('meetingWay').value,
                meetingDetail: document.getElementById('meetingDetail').value,
                firstImpression: document.querySelector('input[name="firstImpression"]:checked')?.value || '随机',
                tones: Array.from(document.querySelectorAll('input[name="tone"]:checked')).map(cb => cb.value),
                rating: document.querySelector('input[name="rating"]:checked')?.value || '暧昧',
                otherNotes: document.getElementById('otherNotes').value
            };

            let output = `【{{user}} 角色档案 - 浮城】

═══════════════════════════════════
基础信息
═══════════════════════════════════
姓名/称呼：${data.name}`;

            if (data.age) output += `\n年龄：${data.age}岁`;
            if (data.gender) output += `\n性别：${data.gender}`;
            if (data.occupation) output += `\n职业/身份：${data.occupation}`;
